export type LogoVariant = keyof typeof logoArt;

/** Standalone SVG markup for files and generated images. */
export function logoSvg(variant: LogoVariant, fill: string): string {
  const art = logoArt[variant];
  const paths = art.paths.map((d) => `<path d="${d}"/>`).join("");
  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="${art.viewBox}"><g transform="${art.transform}" fill="${fill}">${paths}</g></svg>`;
}

